import { ReactNode } from 'react'
import { FieldErrors, FieldValues, UseFormHandleSubmit } from 'react-hook-form'
import { cn } from '@/utils'

export type FormProps<T extends FieldValues> = {
  children: ReactNode
  handleSubmit: UseFormHandleSubmit<T>
  onSubmit: (data: T) => void
  onError?: (errors: FieldErrors<T>) => void
  loading: boolean
  className?: string
  noValidate?: boolean
  id?: string
}

function Form<T extends FieldValues>({
  children,
  handleSubmit,
  onSubmit,
  onError,
  loading,
  className,
  noValidate,
  id,
}: FormProps<T>) {
  const onSubmitHandler = loading ? undefined : handleSubmit(onSubmit, onError)

  return (
    <form
      id={id}
      onSubmit={(e) => {
        e.preventDefault()
        if (onSubmitHandler) {
          onSubmitHandler(e)
        }
      }}
      className={cn(className)}
      noValidate={noValidate}
    >
      {children}
    </form>
  )
}

export default Form

import { describe, expect, it } from 'vitest'
import { render, screen } from '@testing-library/react'

import { FormArrayError } from './FormArrayError'

const GENERIC = 'Vui lòng kiểm tra lại thông tin nhân sự'
const BE_MESSAGE =
  "'EX000001940 - Sàn Tuấn Anh 66' chưa có tỷ lệ hoa hồng: cấu hình TBC hiệu lực vào ngày 2026-08-20 đang để trống tỷ lệ. Hãy điền tỷ lệ trên TBC trước khi tiếp tục."

describe('FormArrayError', () => {
  it('renders nothing when there is no error', () => {
    const { container } = render(<FormArrayError errors={undefined} />)
    expect(container).toBeEmptyDOMElement()
  })

  it('renders the root message when the array itself is invalid', () => {
    render(<FormArrayError errors={{ root: { message: 'Tổng tỷ lệ doanh thu phải bằng 100%' } }} />)
    expect(screen.getByText('Tổng tỷ lệ doanh thu phải bằng 100%')).toBeInTheDocument()
  })

  // Bug 86eyez5z6 — đây là hồi quy chính. BE trả lý do rất rõ theo từng dòng; bản cũ
  // vứt hết và chỉ in một câu chung chung, nên người dùng bị chặn lưu mà không biết
  // phải sửa gì.
  it('surfaces the concrete per-row message instead of the generic fallback', () => {
    render(<FormArrayError errors={[{ exchange: { message: BE_MESSAGE } }]} />)

    expect(screen.getByText(BE_MESSAGE)).toBeInTheDocument()
    expect(screen.queryByText(GENERIC)).not.toBeInTheDocument()
  })

  it('finds a message nested deeper than the first level', () => {
    render(
      <FormArrayError
        errors={[{ f2_source: { type: 'invalid_enum_value', message: 'Nguồn F2 không hợp lệ' } }]}
      />
    )
    expect(screen.getByText('Nguồn F2 không hợp lệ')).toBeInTheDocument()
  })

  it('numbers the rows when more than one row is at fault', () => {
    render(
      <FormArrayError
        errors={[
          { exchange: { message: 'Sàn A chưa có tỷ lệ' } },
          { exchange: { message: 'Sàn B chưa có tỷ lệ' } },
        ]}
      />
    )
    expect(screen.getByText('Dòng 1: Sàn A chưa có tỷ lệ')).toBeInTheDocument()
    expect(screen.getByText('Dòng 2: Sàn B chưa có tỷ lệ')).toBeInTheDocument()
  })

  it('skips rows with no error when numbering', () => {
    render(
      <FormArrayError errors={[undefined, { exchange: { message: 'Sàn B chưa có tỷ lệ' } }]} />
    )
    expect(screen.getByText('Dòng 2: Sàn B chưa có tỷ lệ')).toBeInTheDocument()
  })

  it('falls back to the generic message only when no message can be found', () => {
    render(<FormArrayError errors={[{ exchange: { type: 'required' } }]} />)
    expect(screen.getByText(GENERIC)).toBeInTheDocument()
  })

  // Lỗi thật của react-hook-form mang theo `ref` trỏ tới ô input; React gắn cây fiber
  // (có tham chiếu vòng) lên chính node đó. Nếu hàm gom message đi vào `ref` thì tràn
  // stack và treo form — ca nguy hiểm nhất là `message` rỗng nên không dừng sớm được.
  it('does not walk into the DOM node behind `ref`', () => {
    const input = document.createElement('input')
    ;(input as any).__reactFiber$abc = { stateNode: input }
    ;(input as any).__reactFiber$abc.self = (input as any).__reactFiber$abc

    expect(() =>
      render(
        <FormArrayError errors={[{ exchange: { type: 'required', message: '', ref: input } }]} />
      )
    ).not.toThrow()
    expect(screen.getByText(GENERIC)).toBeInTheDocument()
  })

  it('survives a self-referencing error object', () => {
    const cyclic: Record<string, unknown> = { type: 'required' }
    cyclic.self = cyclic

    expect(() => render(<FormArrayError errors={[cyclic]} />)).not.toThrow()
    expect(screen.getByText(GENERIC)).toBeInTheDocument()
  })

  it('still finds the message when a leaf also carries a ref', () => {
    const input = document.createElement('input')
    render(
      <FormArrayError
        errors={[{ exchange: { type: 'invalid', message: BE_MESSAGE, ref: input } }]}
      />
    )
    expect(screen.getByText(BE_MESSAGE)).toBeInTheDocument()
  })

  it('honours a caller-supplied fallback', () => {
    render(<FormArrayError errors={[{}]} fallbackMessage="Kiểm tra lại các dòng" />)
    expect(screen.getByText('Kiểm tra lại các dòng')).toBeInTheDocument()
  })
})

type FormArrayErrorProps = {
  errors?: unknown
  fallbackMessage?: string
  className?: string
}

/**
 * Gom mọi message thật nằm bên trong lỗi của MỘT dòng.
 *
 * react-hook-form lồng lỗi theo đúng hình dạng của giá trị, nên lỗi một dòng có thể là
 * `{ exchange: { message } }`, `{ f2_source: { message } }`, hay sâu hơn nữa. Đi đệ quy
 * để không phải liệt kê tay từng tên field — danh sách đó chắc chắn sẽ lạc hậu.
 */
const collectMessages = (node: unknown, out: string[], depth = 0, seen = new WeakSet()): void => {
  if (!node || typeof node !== 'object' || depth > 6) return

  // Node DOM là ngõ cụt PHẢI chặn. Lỗi của react-hook-form mang theo `ref` trỏ tới ô
  // input thật; React gắn `__reactFiber$…` lên chính node đó, và cây fiber có tham chiếu
  // vòng. Đi tiếp vào đấy là tràn stack, treo hẳn form.
  if ((node as { nodeType?: number }).nodeType !== undefined) return
  if (seen.has(node as object)) return
  seen.add(node as object)

  const rec = node as Record<string, unknown>
  if (typeof rec.message === 'string' && rec.message.trim()) {
    out.push(rec.message.trim())
    return
  }

  for (const [key, value] of Object.entries(rec)) {
    if (key === 'ref') continue
    collectMessages(value, out, depth + 1, seen)
  }
}

/**
 * Hiện lỗi cấp mảng của một field array (vd `sales_staff`).
 *
 * Trước đây component này nuốt mọi message cụ thể: hễ lỗi là một mảng (tức lỗi nằm ở
 * từng dòng) mà không có message ở gốc thì nó in đúng một câu chung chung, dù message
 * thật của BE đang nằm ngay bên trong. Người dùng bị chặn lưu mà không biết vì sao —
 * bug 86eyez5z6: BE nói rõ "sàn F2 chưa có tỷ lệ hoa hồng trên TBC hiệu lực ngày…",
 * màn hình chỉ nói "Vui lòng kiểm tra lại thông tin nhân sự".
 *
 * Giờ câu chung chung chỉ còn là phương án cuối, khi thật sự không moi được message nào.
 */
export const FormArrayError = ({
  errors,
  fallbackMessage = 'Vui lòng kiểm tra lại thông tin nhân sự',
  className = 'text-xs text-data-red-default mt-2',
}: FormArrayErrorProps) => {
  if (!errors) return null

  const arrayErr = errors as Record<string, any>

  // Lỗi gắn ở gốc mảng (vd "Tổng tỷ lệ doanh thu phải bằng 100%") — ưu tiên tuyệt đối.
  const rootMessage =
    arrayErr?.root?.message ||
    (typeof arrayErr?.message === 'string' && arrayErr.message.trim() ? arrayErr.message : null)
  if (rootMessage) return <p className={className}>{rootMessage}</p>

  if (!Array.isArray(arrayErr)) return null

  // Lỗi theo từng dòng: nêu đúng dòng nào hỏng và hỏng vì sao.
  const perRow: { row: number; message: string }[] = []
  arrayErr.forEach((rowErr, index) => {
    const messages: string[] = []
    collectMessages(rowErr, messages)
    for (const message of new Set(messages)) perRow.push({ row: index + 1, message })
  })

  if (perRow.length === 0) return <p className={className}>{fallbackMessage}</p>

  // Một dòng thì nói thẳng, khỏi đánh số cho rườm rà.
  if (perRow.length === 1 && arrayErr.length <= 1) {
    return <p className={className}>{perRow[0].message}</p>
  }

  return (
    <ul className={className}>
      {perRow.map(({ row, message }) => (
        <li key={`${row}-${message}`}>{`Dòng ${row}: ${message}`}</li>
      ))}
    </ul>
  )
}

import { cn } from '@/utils'

export interface FormCaptionProps {
  caption?: string
  error?: string
  disabled?: boolean
}

export const FormCaption = ({ caption, error, disabled }: FormCaptionProps) => {
  if (!error && !caption) {
    return null
  }

  return (
    <div
      className={cn(
        `text-xs`,
        'text-neutral-80',
        disabled && 'text-content-dark-4',
        error && 'text-data-red-default'
      )}
    >
      {error || caption}
    </div>
  )
}

import { describe, expect, it } from 'vitest'
import { act, fireEvent, render, screen } from '@testing-library/react'
import { forwardRef } from 'react'
import { Controller, useForm, useWatch, type UseFormReturn } from 'react-hook-form'
import FormController from './FormController'
import { CurrencyInput } from '@/components/ui/currency-input/CurrencyInput'

/**
 * Khoá lại lý do `FormController` tự đọc giá trị bằng `useWatch` thay vì dùng `field.value`.
 *
 * Bẫy nằm ở react-hook-form, không ở component nhập liệu: `useController` dựng `field.value` bằng
 * `useWatch(defaultValue = get(_formValues, name, get(_defaultValues, name)))`, và cái default ấy
 * được CHỤP Ở LẦN RENDER ĐẦU. Hàm `get` của RHF trả về default mỗi khi giá trị là `undefined`, nên
 * field bị xoá trắng lại nhận về GIÁ TRỊ BAN ĐẦU — ở màn Sửa là dữ liệu từ server.
 *
 * Bug thật: ClickUp 86eyqrt6r, ô "Số tiền thanh toán" của HĐ đặt chỗ.
 */

type Values = { amount?: number }

const SAVED_AMOUNT = 2000000

let formApi: UseFormReturn<Values>

/** Không đặt tên mở đầu bằng `render` — `testing-library/render-result-naming-convention` bắt. */
const amountBox = () => screen.getByRole('textbox') as HTMLInputElement

/**
 * Tái hiện đúng thao tác của QA: gõ bớt cho giá trị KHÁC giá trị đã lưu, rồi mới xoá trắng.
 *
 * Thứ tự này là bắt buộc, không phải cho đẹp. Xoá trắng thẳng từ giá trị gốc thì `field.value` đi
 * từ 2000000 về đúng 2000000 (default), React bail-out, component không re-render và ô vẫn rỗng —
 * trông như không có lỗi, dù form state đã lệch khỏi thứ đang hiện.
 */
const typeDownThenClear = (input: HTMLInputElement) => {
  fireEvent.change(input, { target: { value: '2' } })
  fireEvent.change(input, { target: { value: '' } })
}

const AmountForm = ({ defaults }: { defaults: Values }) => {
  const form = useForm<Values>({ defaultValues: defaults })
  formApi = form
  return (
    <FormController<Values, Record<string, unknown>>
      register={form.register}
      control={form.control}
      name="amount"
      Field={CurrencyInput}
    />
  )
}

describe('FormController — giá trị hiển thị (86eyqrt6r)', () => {
  it('xoá trắng được ô ở form CÓ giá trị mặc định — đây là bug gốc', () => {
    render(<AmountForm defaults={{ amount: SAVED_AMOUNT }} />)
    const input = amountBox()
    expect(input.value).toBe('2.000.000') // tiền đề: form đã nạp giá trị đã lưu

    typeDownThenClear(input)

    expect(input.value).toBe('')
    expect(formApi.getValues('amount')).toBeUndefined()
  })

  it('xoá xong gõ số mới thì nhận đúng số mới, không dính lại số cũ', () => {
    render(<AmountForm defaults={{ amount: SAVED_AMOUNT }} />)
    const input = amountBox()

    typeDownThenClear(input)
    fireEvent.change(input, { target: { value: '350000' } })

    expect(input.value).toBe('350.000')
    expect(formApi.getValues('amount')).toBe(350000)
  })

  it('form KHÔNG có giá trị mặc định (màn Tạo) vẫn chạy như cũ', () => {
    render(<AmountForm defaults={{}} />)
    const input = amountBox()
    fireEvent.change(input, { target: { value: '350000' } })
    expect(input.value).toBe('350.000')

    fireEvent.change(input, { target: { value: '' } })

    expect(input.value).toBe('')
    expect(formApi.getValues('amount')).toBeUndefined()
  })

  it('vẫn hiển thị giá trị do form đặt vào (setValue), không phải chỉ hiển thị thứ user gõ', () => {
    render(<AmountForm defaults={{ amount: SAVED_AMOUNT }} />)
    const input = amountBox()

    // `setValue` gọi trần không nằm trong act() nên React 18 không xả update — phải bọc, không thì
    // test đỏ vì hạ tầng chứ không phải vì code.
    act(() => {
      formApi.setValue('amount', 777000)
    })

    expect(input.value).toBe('777.000')
  })

  it('field lồng trong mảng vẫn cập nhật khi form ghi đè CẢ mảng cha', () => {
    // 52 chỗ trong repo khai `name={`rows.${i}.x`}` qua FormController, và nhiều form ghi lại cả
    // mảng bằng `setValue('rows', ...)` (vd BookingContractForm khi đổi hoa hồng). `useWatch` của
    // FormController đăng ký `exact: true`; test này chốt rằng lượt ghi cả mảng vẫn lan xuống ô con.
    type Rows = { rows: { v?: number }[] }
    let api: UseFormReturn<Rows>
    const RowsForm = () => {
      const form = useForm<Rows>({ defaultValues: { rows: [{ v: 1000 }, { v: 2000 }] } })
      api = form
      return (
        <FormController<Rows, Record<string, unknown>>
          register={form.register}
          control={form.control}
          name="rows.0.v"
          Field={CurrencyInput}
        />
      )
    }

    render(<RowsForm />)
    expect(amountBox().value).toBe('1.000') // tiền đề: ô con đọc đúng phần tử đầu

    act(() => {
      api.setValue('rows', [{ v: 9000 }, { v: 8000 }])
    })

    expect(amountBox().value).toBe('9.000')
  })

  it('`fieldProps` vẫn đứng cuối nên call site đè được mọi prop, kể cả `value`', () => {
    // forwardRef vì `{...field}` có kèm `ref`; thiếu nó React cảnh báo giữa output test.
    const Probe = forwardRef<HTMLSpanElement, { value?: unknown }>(({ value }, ref) => (
      <span ref={ref}>hiển thị: {String(value)}</span>
    ))
    const Harness = () => {
      const form = useForm<Values>({ defaultValues: { amount: SAVED_AMOUNT } })
      return (
        <FormController<Values, Record<string, unknown>>
          register={form.register}
          control={form.control}
          name="amount"
          Field={Probe}
          fieldProps={{ value: 'GIA_TRI_DE' }}
        />
      )
    }

    render(<Harness />)

    expect(screen.getByText('hiển thị: GIA_TRI_DE')).toBeInTheDocument()
    // Đối chứng: không đè thì chính giá trị form mới là thứ tới nơi.
    expect(screen.queryByText(`hiển thị: ${SAVED_AMOUNT}`)).toBeNull()
  })
})

describe('react-hook-form — tiền đề khiến bản vá trên tồn tại', () => {
  it('`field.value` của Controller trần VẪN trả về giá trị mặc định khi form state là undefined', () => {
    // Test này KHÔNG mô tả hành vi mong muốn — nó chốt hành vi của thư viện. Ngày nào RHF bỏ nhánh
    // fallback đó thì test này đỏ, và người sửa biết `value={liveValue}` trong FormController đã
    // hết cần thiết. Đừng "sửa cho xanh" bằng cách đổi expectation.
    const RawHarness = () => {
      const form = useForm<Values>({ defaultValues: { amount: SAVED_AMOUNT } })
      formApi = form
      const live = useWatch({ control: form.control, name: 'amount' })
      return (
        <>
          <Controller
            control={form.control}
            name="amount"
            render={({ field }) => <CurrencyInput {...field} />}
          />
          <span data-testid="live">{String(live)}</span>
        </>
      )
    }

    render(<RawHarness />)
    const input = amountBox()

    typeDownThenClear(input)

    expect(input.value).toBe('2.000.000') // field.value hồi sinh giá trị ban đầu
    expect(formApi.getValues('amount')).toBeUndefined() // trong khi form state đã rỗng
    expect(screen.getByTestId('live')).toHaveTextContent('undefined') // useWatch nói thật
  })
})

import { Control, Controller, FieldValues, Path, UseFormRegister, useWatch } from 'react-hook-form'
import { ElementType } from 'react'

type Props<FormType extends FieldValues, FieldProps> = {
  register: UseFormRegister<FormType>
  name: Path<FormType>
  control: Control<FormType, any, any>
  Field: ElementType
  fieldProps?: FieldProps
  wrapperClassName?: string
}

function FormController<FormType extends FieldValues, FieldProps>({
  name,
  control,
  Field,
  fieldProps,
  wrapperClassName,
}: Props<FormType, FieldProps>) {
  /**
   * Giá trị hiển thị lấy từ đây, ĐỪNG dùng `field.value` của `Controller` (nó được đè bên dưới).
   *
   * `useController` dựng `field.value` bằng
   * `useWatch(defaultValue = get(_formValues, name, get(_defaultValues, name)))`, và cái default ấy
   * được CHỤP Ở LẦN RENDER ĐẦU. Hàm `get` của RHF trả về default **mỗi khi giá trị là `undefined`**
   * ⇒ field bị xoá trắng lại nhận về GIÁ TRỊ BAN ĐẦU, ở màn Sửa là dữ liệu từ server. Người dùng
   * thấy "xoá không được"; form state thì đã rỗng, tức thứ đang hiện và thứ sắp gửi đi là hai giá
   * trị khác nhau. Đã thành bug thật ở ô "Số tiền thanh toán" (ClickUp 86eyqrt6r). Ba component
   * dùng chung bắn `undefined` khi rỗng: `CurrencyInput`, `date-time-picker`, `MonthPicker`.
   *
   * ĐỪNG chữa ở phía component bằng cách bắn `null`/`''` thay `undefined`: `z.coerce` biến cả hai
   * thành 0 và cho qua `.min(0)` ⇒ ô bắt buộc âm thầm lưu 0 thay vì chặn.
   *
   * `exact: true` khớp đúng cách `useController` tự đăng ký (`react-hook-form@7.63` dựng
   * `useWatch({ control, name, defaultValue, exact: true })`), nên lượt này báo đúng vào những nhịp
   * mà `Controller` cũng re-render — không thêm nhịp render nào. Field lồng trong mảng vẫn nhận
   * được lượt ghi đè cả mảng cha (`setValue('rows', …)`); có test khoá.
   *
   * Không truyền `defaultValue`: `_getWatch` khi form CHƯA mount và `defaultValue` là `undefined`
   * thì đọc `_defaultValues`, y hệt `field.value` ở lần render đầu, nên không có nháy giá trị.
   */
  const liveValue = useWatch({ control, name, exact: true })

  return (
    <div data-field-name={name} className={wrapperClassName}>
      <Controller
        control={control}
        name={name}
        render={({ field, fieldState }) => {
          // `value` đè `field.value` (xem docblock trên). `fieldProps` vẫn đứng CUỐI để call site
          // đè được khi thật sự cần — thứ tự đó là hợp đồng, có test khoá.
          return (
            <Field {...field} value={liveValue} error={fieldState.error?.message} {...fieldProps} />
          )
        }}
      />
    </div>
  )
}

export default FormController
